from __future__ import annotations

import os
from pathlib import Path

COOKIE_NAMES = ("sessionid", "sessionid_ss", "sid_tt")


def write_tiktok_cookies(
    path: Path, session_id: str, target_idc: str = ""
) -> bool:
    """Write a Netscape cookie file for yt-dlp.

    Returns True when a file was written, False when no session id is set.
    """
    session = (session_id or "").strip()
    if not session:
        return False

    lines = [
        "# Netscape HTTP Cookie File",
        "# Generated by Restreamer",
        "",
    ]
    for name in COOKIE_NAMES:
        lines.append(f".tiktok.com\tTRUE\t/\tTRUE\t0\t{name}\t{session}")
    idc = (target_idc or "").strip()
    if idc:
        lines.append(f".tiktok.com\tTRUE\t/\tTRUE\t0\ttt-target-idc\t{idc}")
    lines.append("")

    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text("\n".join(lines), encoding="utf-8")
    try:
        os.chmod(tmp, 0o600)
    except OSError:
        pass
    os.replace(tmp, path)
    return True
